function updateRun(dt){
R.step(state,dt);const jumpButton=$('[data-action="jump"]');jumpButton.disabled=state.phase!=='active'||state.jumpCooldown>0;jumpButton.textContent=state.jump>0?'正在空中':state.jumpCooldown>0?'落地稳一下':'跳一下 · 空格';score(state.distance,'%');setCounter(Math.max(0,20-state.t).toFixed(1)+' 秒 · '+'♥ '.repeat(Math.max(0,state.hp)));
for(const event of state.events){if(event.type==='food'){particles(runnerX(state.drawLane,1),540,['#fff4af','#ffc682']);feedback('早餐带上！+20',3);}else if(event.type==='jump'){feedback('跨过去了！',2);}else if(event.type==='collision'){feedback('撞到了，速度掉下来了！',0);}}
const incoming=state.waves.find(w=>!w.checked&&w.at-state.track<R.LOOKAHEAD*.86);const names=['左','中','右'];canvas.setAttribute('aria-label','早八赶路试玩画面，当前'+names[state.lane]+'道'+(incoming?'，前方'+incoming.objects.map(o=>names[o.lane]+'道'+({barrier:'高路障',cone:'矮路障',breakfast:'早餐'}[o.kind])).join('、'):''));
if(state.phase==='done'){const value=R.resultScore(state);if(state.won){particles(480,290,['#ffe7a2','#9cd5b7'],25);finish('铃响之前，冲进教室！','提前 '+(20-state.t).toFixed(1)+' 秒到达 · '+value+' 分。试玩只记录成绩。',value);}else finish(state.reason==='collision'?'撞了三次，没赶上。':'铃响了，还没到教室。',(state.reason==='collision'?'赶路中断':'减速耽误了时间')+' · 跑完 '+state.distance+'% · '+value+' 分。再试一轮。',value);}
}
